hints.code_snippet:
class BankAccount {
  #balance;

  constructor(startingBalance = 0) {
    this.#balance = startingBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.#balance += amount;
    }
  }

  withdraw(amount) {
    const currentBalanceInfo = this.getBalance();
    if (amount > 0 && currentBalanceInfo.value >= amount) {
      this.#balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return { value: this.#balance };
  }
}

